    let mut score = post_residual as f64;

    // Favor bins with more remaining capacity
    score += (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 15.0;

    // Penalize creating new bins if possible
    if fitting_bins_count > 0 {
        score -= 2.5;
    }

    // Favor bins with lower mean residual to balance load across bins
    score += mean_residual * 0.8;

    // Reward items that fit exactly in the current bin (zero waste)
    if post_residual == 0 {
        score += 30.0;
    }

    // Penalize large items when there are few fitting bins left
    if item_size > 45 && fitting_bins_count <= 2 {
        score -= 16.0;
    }

    // Favor bins with a smaller next item to allow for better packing
    if next_item_size < item_size {
        score += (item_size - next_item_size) as f64 / item_size as f64 * 4.5;
    }

    // Penalize bins where the next item is much larger than the current bin
    if next_item_size > 2 * item_size {
        score -= 12.0;
    }

    // Reward bins with a lower residual variance across items
    let residual_variance = mean_residual / bin_capacity as f64;
    score += (1.0 - residual_variance) * 7.5;

    // Penalize the use of open bins to reduce overall count
    if open_bins_count > 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
