pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = -post_residual as f64;

    // Adjust score based on item size and bin residual
    if post_residual < item_size / 2 {
        score -= (item_size - post_residual) as f64 * 1.5;
    } else if post_residual > item_size * 2 {
        score += (post_residual - item_size * 2) as f64 * 0.5;
    }

    // Penalize if no fitting bins are available
    if fitting_bins_count == 0 {
        score += open_bins_count as f64 * 1.0;
    } else if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Reward if mean residual is closer to post residual
    if mean_residual < post_residual as f64 / 2.0 {
        score += (post_residual - mean_residual) as f64 * 0.5;
    } else if mean_residual > post_residual as f64 * 1.5 {
        score -= (mean_residual - post_residual as f64 * 1.5) as f64 * 0.25;
    }

    // Adjust score based on next item size
    if next_item_size < bin_capacity / 3 {
        score += next_item_size as f64 * 0.75;
    } else if next_item_size > bin_capacity * 2 / 3 {
        score -= (next_item_size - bin_capacity * 2 / 3) as f64 * 1.0;
    }

    // Combine scores with weighted averages
    let score = score * 0.70 + ((post_residual as f64) as f64) * 0.30;
    score
}

